    return None


def run(store, operation, item):
    updated = _x28_update(store, operation, item)
    if updated is not None:
        return updated
    if operation != 'check':
        return False
    if not store.preliminary(item):
        return False
    page = store.page_for(item)
    if item in store.read_page(page):
        store.grants.append(item)
